val Ttl = 2
  var s: {
    now: int, active: Set[str], byRun: str -> List[str], recorded: str -> int,
    created: str -> int, enriched: Set[str]
  }

val IndexAgreesWithOwners = Runs.forall(ownerRun => {
    val index = s.byRun.get(ownerRun)
    index.indices().map(i => index.nth(i)) == s.active.filter(t => Owner.get(t) == ownerRun)
  })

val IndexKeepsInsertionOrder = Runs.forall(ownerRun => {
    val index = s.byRun.get(ownerRun)
    index.indices().forall(i => index.indices().forall(j =>
      (i < j).implies(s.recorded.get(index.nth(i)) < s.recorded.get(index.nth(j)))))
  })

val LatestIsNewest = Runs.forall(ownerRun =>
    s.active.filter(t => Owner.get(t) == ownerRun).forall(t => {
      val current = latest(ownerRun)
      if (current == "") false else s.recorded.get(t) <= s.recorded.get(current)
    }))

temporal EnrichmentStaysInOneRun = always(Runs.exists(ownerRun =>
    next(s.enriched).exclude(s.enriched).subseteq(s.active.filter(t => Owner.get(t) == ownerRun))
  ).orKeep(s))

val Limit = 4
  var s: { runs: str -> Run, phase: str, active: str, base: int,
    received: List[int], requested: str, saved: str, session: str,
    failed: bool }

val DiagnosticsFollowOriginal = all {
    (s.phase == "original").implies(s.received.length() == 0),
    (s.phase == "report").implies(s.received.length() == 1),
    (s.phase == "warning").implies(s.received.length() == 2),
    (s.phase == "idle" and s.failed).implies(s.received.length() == 3),
  }

val Heartbeats = Set("sent", "failed")
  var s: { registrations: str -> Registration, lastHeartbeat: str,
    indicator: str, operation: str, channel: str, handle: int, previous: int }

val OneCurrentRegistration = Channels.forall(channel => {
    val current = s.registrations.get(channel)
    current.active == 0 or current.active == current.generation
  })

val HeartbeatStatusMatchesIndicator = all {
    (s.lastHeartbeat == "sent").implies(s.indicator == "alert"),
    (s.lastHeartbeat == "failed").implies(s.indicator == "error"),
    (s.lastHeartbeat == "none").implies(s.indicator == "none"),
  }

val route = if (Mode == "send") {
    if (s.handlers.get(Target) != 0) Target else if (s.handlers.get(0) != 0) 0 else -1
  } else if (s.descriptors.contains(Target)) Target
    else if (Mode == "hook" and s.descriptors.contains(0)) 0 else -1

val RegistryShape = and {
    s.descriptors.subseteq(routes), routes.forall(r => Set(0, 1, 2).contains(s.handlers.get(r))),
    Set(-1, 0, 1).contains(s.selectedRoute), Set(0, 1, 2).contains(s.selectedOwner)
  }

val MissingNeverInvokes = s.result == "missing" implies and {
    s.phase == "done", s.selectedOwner == 0, s.selectedRoute == -1, s.invoked == 0
  }

val UnsupportedNeverInvokes = s.result == "unsupported" implies and {
    s.phase == "done", s.selectedOwner == 0, s.selectedRoute != -1, s.invoked == 0
  }

val ResultRequiresSettlement = Set("ok", "failed").contains(s.result) implies and {
    s.phase == "done", s.invoked != 0
  }

temporal AdmissionSelectsRoute = always(((s.phase == "idle" and next(s.phase) != "idle") implies and {
    next(s.selectedRoute) == route, next(s.selectedOwner) == owner
  }).orKeep(s))

temporal AdmittedOwnerStays = always(((s.phase != "idle") implies and {
    next(s.selectedRoute) == s.selectedRoute, next(s.selectedOwner) == s.selectedOwner
  }).orKeep(s))

temporal FairDispatchFinishes = and {
    resumeDispatch.weakFair(s), settleHandler.weakFair(s)
  } implies DispatchFinishes

val EachRegistrationOnce =
    attempts.indices().forall(i => attempts.indices().forall(j =>
      i >= j or attempts[i] < attempts[j]))

  // Bounded retries: after a provider exhausts its own retry budget, no other
  // registration of that provider runs in this dispatch.

val ExhaustedProviderSkipped =
    attempts.indices().forall(i => attempts.indices().forall(j =>
      i >= j or outcomeOf(attempts[i]) != BUDGET_EXHAUSTED or
        providerOf(attempts[j]) != providerOf(attempts[i])))

  // Terminal precedence: funding, policy, cancellation and a request error
  // end the dispatch even when their cause is a refused connection, and
  // TEXT_TO_SPEECH never fails over.

val TerminalOutcomeEndsDispatch =
    attempts.indices().forall(i =>
      i == attempts.length() - 1 or
        (modelType == 0 and not(Set(3, 4, 5, 6, 7).contains(outcomeOf(attempts[i])))))

  // Nested causes and provider exhaustion: a TEXT_SMALL refused connection,
  // on the SDK error's cause or inside a retry envelope, or an exhausted
  // provider budget reaches the next registration whose provider has budget;
  // the dispatch rejects with it only when no such registration is left.

val Registry = Set("mutator", "original", "removable", "reader-a", "reader-b")
  type Dispatch = {
    status: str, captured: Set[str], started: Set[str], done: Set[str],
    group: int, diagnostic: bool, refusedBy: Set[str]
  }
  var s: { registry: Set[str], calls: str -> Dispatch }

val StartsOnlyCaptured = Calls.forall(call => {
    val dispatch = s.calls.get(call)
    dispatch.done.subseteq(dispatch.started) and dispatch.started.subseteq(dispatch.captured)
  })

val GroupsWaitForCompletion = Calls.forall(call => {
    val dispatch = s.calls.get(call)
    val selected = groups(dispatch.captured)
    0.to(selected.length() - 1).forall(group => and {
      (group + 1 < dispatch.group).implies(selected[group].subseteq(dispatch.done)),
      (group >= dispatch.group).implies(selected[group].intersect(dispatch.started) == Set()),
    })
  })

val HonestSettlement = Calls.forall(call => {
    val dispatch = s.calls.get(call)
    and {
      (dispatch.status == "fulfilled").implies(dispatch.done == dispatch.captured),
      (dispatch.status == "rejected") == (dispatch.refusedBy.size() == 1),
      dispatch.refusedBy.subseteq(Targets.intersect(dispatch.done)),
      (dispatch.status == "rejected").implies(not(Parallel)
        and not(dispatch.started.contains("reader-a")) and not(dispatch.started.contains("reader-b"))),
      dispatch.diagnostic.implies(dispatch.refusedBy == Set()
        and Targets.intersect(dispatch.done).size() == 1),
    }
  })

temporal SnapshotSelection = always(Calls.forall(call => and {
    (s.calls.get(call).status == "idle" and next(s.calls.get(call).status) != "idle")
      .implies(next(s.calls.get(call).captured) == s.registry),
    (s.calls.get(call).status != "idle")
      .implies(next(s.calls.get(call).captured) == s.calls.get(call).captured),
  }).orKeep(s))

temporal Fairness = and {
    Execs.forall(e => SettleAborted(e).weakFair(s) and Cleanup(e).weakFair(s)),
    Callers.forall(c => CallerSettle(c).weakFair(s)), StopComposer.weakFair(s)
  }

temporal StopReleasesCallers = Fairness.implies(Callers.forall(c =>
    (s.pc.get(c) == "attached" and s.stopped).leadsTo(s.pc.get(c) == "done")))
  // Once the work settles, callbacks must finish regardless of its outcome.
  // This property does not assume that non-aborted provider work settles.

temporal SettledCallerLeaves = and {
    Execs.forall(e => Cleanup(e).weakFair(s)),
    Callers.forall(c => CallerSettle(c).weakFair(s))
  }.implies(Callers.forall(c =>
    (s.pc.get(c) == "attached" and s.phase.get(s.exec.get(c)) != Pending).leadsTo(s.pc.get(c) == "done")))

temporal Fairness = and {
    Rooms.forall(r => Grant(r).weakFair(s)),
    Turns.forall(t => Admit(t).weakFair(s) and StartRelease(t).weakFair(s) and StopWrites(t).weakFair(s) and Release(t).weakFair(s)),
    Turns.forall(t => Rooms.forall(r => EndWrite(t, r).weakFair(s)))
  }

val TypeOK = and {
    s.queue.keys() == Rooms, s.active.keys() == Rooms, s.want.keys() == Turns,
    s.held.keys() == Turns, s.pc.keys() == Turns, s.accepting.keys() == Turns, s.writes.keys() == Turns,
    Rooms.forall(r => Turns.union(Set(None)).contains(s.active.get(r)) and s.queue.get(r).indices().forall(i => Turns.contains(s.queue.get(r).nth(i)))),
    Turns.forall(t => and {
      s.want.get(t).subseteq(Rooms), s.held.get(t).subseteq(Rooms),
      States.contains(s.pc.get(t)), s.accepting.get(t).subseteq(Rooms),
      s.writes.get(t).keys() == Rooms,
      Rooms.forall(r => s.writes.get(t).get(r) >= 0 and s.writes.get(t).get(r) <= MaxWrites)
    })
  }

val MutualExclusion = and {
    Rooms.forall(r => (s.active.get(r) != None).implies(s.held.get(s.active.get(r)).contains(r))),
    Turns.forall(t => s.held.get(t).forall(r => s.active.get(r) == t))
  }

val WritesUnderLease = Turns.forall(t => and {
    s.accepting.get(t).subseteq(s.held.get(t)),
    Rooms.forall(r => (s.writes.get(t).get(r) > 0).implies(s.held.get(t).contains(r))),
    Set("done", "refused", "cancelled", "idle").contains(s.pc.get(t)).implies(Rooms.forall(r => s.writes.get(t).get(r) == 0))
  })

temporal FreedByOwner = always(Rooms.forall(r =>
    (s.active.get(r) != None and next(s.active).get(r) != s.active.get(r)).implies(and {
      Set("releasing", "unwinding").contains(s.pc.get(s.active.get(r))),
      not(s.accepting.get(s.active.get(r)).contains(r)), s.writes.get(s.active.get(r)).get(r) == 0
    })).orKeep(s))

val ReportsFirstFailure = and {
    s.firstFailure != 0 implies s.handlers.get(s.firstFailure) == "rejected",
    (s.emitResult == "failed") == (s.emitResult != "none" and s.firstFailure != 0)
  }

temporal FirstRequestAndFailureStay = always(and {
    s.outcome != "none" implies and {
      next(s.outcome) == s.outcome, next(s.capturedReceipt) == s.capturedReceipt,
      s.work == "new" implies next(s.work) == "new"
    },
    s.firstFailure != 0 implies next(s.firstFailure) == s.firstFailure
  }.orKeep(s))

temporal Fairness = and {
    settleDelivery.weakFair(s), finishWork.weakFair(s), emit.weakFair(s),
    settleHandler(1).weakFair(s), settleHandler(2).weakFair(s), returnTerminal.weakFair(s)
  }

val Finished = and {
    Set("idle", "ok", "failed").contains(s.ipc), not(Set("waitInit", "starting", "stopping").contains(s.svc)),
    Pending.size() == 0, s.apc == "none", Stoppers.forall(caller => Set("idle", "done").contains(s.spc.get(caller)))
  }

temporal Fairness = and {
    ICore.weakFair(s), SvcResume.weakFair(s), SvcStarted.weakFair(s), SvcStopDone.weakFair(s), TGrant.weakFair(s),
    Turns.forall(t => TRun(t).weakFair(s) and TFinish(t).weakFair(s)),
    ADrained.weakFair(s), AServices.weakFair(s), ASvcDone.weakFair(s),
    Stoppers.forall(caller => SBestEffortDone(caller).weakFair(s) and SStrictDrain(caller).weakFair(s) and SAwaitStrict(caller).weakFair(s))
  }

temporal Fairness = and {
    Callers.forall(e => EEnsure(e).weakFair(s) and ESettle(e).weakFair(s) and EDelay(e).weakFair(s)),
    Classes.forall(c => StartSettles(c).weakFair(s) and StartEvent(c).weakFair(s) and StartLateStopped(c).weakFair(s)),
    Inst.forall(i => StopOpDone(i).weakFair(s)), RServices.weakFair(s), RStopNext.weakFair(s), RStopWait.weakFair(s), RClear.weakFair(s),
    UAwaited.weakFair(s), UDrain.weakFair(s), UStopped.weakFair(s)
  }

val TypeOK = and {
    s.types.subseteq(Classes), s.byClass.keys() == Classes, s.starting.keys() == Classes, s.failed.keys() == Classes,
    s.sc.keys() == Classes, s.att.keys() == Classes, s.scInst.keys() == Classes,
    Classes.forall(c => and {
      Inst.union(Set(0)).contains(s.byClass.get(c)),
      InFlight.union(Set("idle")).contains(s.sc.get(c)),
      s.att.get(c) >= 0, Inst.union(Set(0)).contains(s.scInst.get(c))
    }),
    s.published.subseteq(Inst), Set("pending", "registering", "registered", "failed", "unknown").contains(s.status), s.nextInst >= 1 and s.nextInst <= MaxInst + 1,
    s.cls.keys() == Inst, s.late.keys() == Inst, s.stopCalls.keys() == Inst, s.stopOp.keys() == Inst,
    Inst.forall(i => Classes.union(Set(None)).contains(s.cls.get(i)) and s.stopCalls.get(i) >= 0 and Set("none", "running", "done").contains(s.stopOp.get(i))),
    s.epc.keys() == Callers, s.ewait.keys() == Callers,
    Callers.forall(e => and {
      Set("idle", "ensure", "wait", "delay", "done").contains(s.epc.get(e)),
      s.ewait.get(e).keys() == Classes, Classes.forall(c => s.ewait.get(e).get(c) >= 0)
    }),
    Set("idle", "services", "stopping", "stopInst", "done").contains(s.rpc), Callers.union(Set(None)).contains(s.lastEnsure),
    Set("idle", "wait", "drain", "stop", "done").contains(s.upc), s.uwait.keys() == Classes, Classes.forall(c => s.uwait.get(c) >= 0)
  }

temporal Fairness = and {
    Unloaders.forall(u => Unload(u).weakFair(s)), Loaders.forall(l => Load(l).weakFair(s)),
    Classes.forall(c => SDone(c).weakFair(s)), Stoppers.forall(t => Stop(t).weakFair(s)),
    Rivals.forall(b => BReg(b).weakFair(s)), Registrars.forall(r => Register(r).weakFair(s))
  }

val TypeOK = and {
    s.types.subseteq(Classes), s.byClass.keys() == Classes, s.starting.keys() == Classes,
    Classes.forall(c => s.byClass.get(c) >= 0 and s.byClass.get(c) <= MaxInst and s.starting.get(c) >= 0 and s.starting.get(c) <= MaxInst),
    s.failedC.subseteq(Classes), s.services.subseteq(Insts), s.live.subseteq(Insts), s.stopOps.subseteq(Insts),
    s.stopCalls.keys() == Insts, Insts.forall(i => s.stopCalls.get(i) >= 0),
    Set("A", "B", "none").contains(s.registry), Set("A", "B", "none").contains(s.lastReg),
    match s.running { NoRunning => true | Actor(a) => Actors.contains(a) | Class(c) => Classes.contains(c) }
  }

val ConnectorOwnedByLast = and {
    (s.owned and s.ownsA and s.tdActive == None).implies(s.registry == "A"),
    s.ownsB.implies(s.registry == "B"), (s.lastReg == "B").implies(s.registry == "B")
  }

val TaskIndexesAgree = and {
    s.runtimeIndex == Tasks.filter(t => Set("queued", "waiting", "running").contains(s.task.get(t))),
    Rooms.forall(r => s.roomIndex.get(r) == s.runtimeIndex.filter(t => s.room.get(t) == r))
  }

temporal DrainsFinishExpanded = Fairness implies and {
    always(s.runtimeDrain == "waiting" implies eventually(s.runtimeDrain != "waiting")),
    Rooms.forall(r => always(s.roomDrain.get(r) == "waiting" implies eventually(s.roomDrain.get(r) != "waiting"))),
    Rooms.forall(r => always(s.boundary.get(r) == "pending" implies eventually(s.boundary.get(r) == "closed")))
  }

  // Each of the two room observers/boundaries and the runtime observer can
  // start once. Under these finite, monotone observer states, every started
  // observer eventually finishing is equivalent to eventual permanent
  // quiescence. The compact form uses one TLC liveness graph rather than five.
  // DrainsFinishExpanded above retains the per-observer statement explicitly.

val ObserversQuiescent = and {
    s.runtimeDrain != "waiting",
    Rooms.forall(r => s.roomDrain.get(r) != "waiting"),
    Rooms.forall(r => Set("none", "closed").contains(s.boundary.get(r)))
  }
